import {MCP23S17} from './mcp23s17.js';import {pinVoltage,poweredDevice,logic} from './bus-electrical.js';import {deviceDefinition} from './device-registry.js';
export function attachSPIGPIORuntime(runtime,engine,initial){let project=initial,states=new Map(),disposed=false,busy=false,key='';
 const refresh=()=>{if(disposed||busy)return;busy=true;try{const dc=engine.solution,drivers=[],adj=new Map();for(const b of dc.branches)for(const[a,c]of[[b.a,b.b],[b.b,b.a]]){if(!adj.has(a))adj.set(a,[]);adj.get(a).push(c);}const supply=(node,owners)=>{const seen=new Set([node]),queue=[node];for(let i=0;i<queue.length;i++){const at=queue[i];if(dc.known.has(at)&&dc.known.get(at)>=1.8){if(!String(at).startsWith('$driver:'))return true;const owner=String(at).split(':')[1],c=project.components.find(c=>c.id===owner),power=c?.type==='mcp23s17'?{vcc:'VDD',gnd:'VSS',min:1.8,max:5.5}:deviceDefinition(c?.type)?.power;if(power&&!owners.has(owner)){const p=poweredDevice(dc,owner,power);if(p.powered&&supply(dc.netlist.net(owner+':'+power.vcc),new Set([...owners,owner])))return true;}}for(const n of adj.get(at)||[])if(!seen.has(n)){seen.add(n);queue.push(n);}}return false;};
 for(const d of states.values()){const v=pin=>pinVoltage(dc,d.id,pin),p=poweredDevice(dc,d.id,{vcc:'VDD',gnd:'VSS',min:1.8,max:5.5});p.powered=p.powered&&supply(dc.netlist.net(d.id+':VDD'),new Set([d.id]));const reset=logic(v('RESET'),p.voltage)!==true,cs=logic(v('CS'),p.voltage),clock=logic(v('SCK'),p.voltage),input=logic(v('SI'),p.voltage),straps=['A0','A1','A2'].map(pin=>logic(v(pin),p.voltage));d.address=straps.reduce((a,b,i)=>a|(b?1<<i:0),0);const over=['SI','SCK','CS','RESET','A0','A1','A2'].some(pin=>v(pin)>p.voltage+.3);if(d.powered&&!p.powered||reset&&!d.resetAsserted)d.controller.reset();Object.assign(d,p);d.resetAsserted=reset;d.overvoltage=over;d.connected=p.powered&&!reset&&!over&&cs!==null&&clock!==null&&input!==null&&straps.every(b=>b!==null);
 if(p.powered&&!reset&&!over)d.controller.inputLevels(Array.from({length:16},(_,i)=>logic(v('GP'+(i<8?'A':'B')+(i&7)),p.voltage)));
 if(!d.connected||cs!==false){d.controller.select();d.bits=0;d.shift=0;d.txBit=0;d.output=null;}else{if(d.cs!==false){d.controller.select();d.bits=0;d.shift=0;d.txBit=0;d.output=null;}if(clock===true&&d.clock===false){d.shift=(d.shift<<1)|(input?1:0);if(++d.bits===8){d.controller.transfer(d.shift&255,d.address);d.bytes++;d.bits=0;d.shift=0;d.txBit=0;}}if(clock===false&&d.clock===true&&d.controller.tx!==null){d.output=(d.controller.tx>>(7-d.txBit))&1;d.txBit=(d.txBit+1)%8;}}
 if(p.powered&&!reset&&!over){for(const driver of d.controller.drivers(p.voltage,0))drivers.push({...driver,endpoint:d.id+':'+driver.pin});if(d.connected&&cs===false&&d.output!==null)drivers.push({endpoint:d.id+':SO',voltage:d.output?p.voltage:0,ohms:50});}d.cs=cs;d.clock=clock;
 }const next=JSON.stringify(drivers);if(next!==key){key=next;engine.setDrivers('spi-gpio',drivers);}}finally{busy=false;}};
 const reconcile=()=>{const ids=new Set();for(const c of project.components.filter(c=>c.type==='mcp23s17')){ids.add(c.id);if(!states.has(c.id))states.set(c.id,{id:c.id,controller:new MCP23S17(),powered:false,bits:0,shift:0,bytes:0,txBit:0,output:null,cs:null,clock:null});}for(const id of states.keys())if(!ids.has(id))states.delete(id);refresh();};reconcile();const unsubscribe=engine.subscribe(refresh);return{updateProject(next){project=next;reconcile();},snapshot(){refresh();return{modules:Object.fromEntries([...states].map(([id,d])=>[id,{type:'mcp23s17',powered:d.powered,connected:d.connected,address:d.address,resetAsserted:d.resetAsserted,overvoltage:d.overvoltage,bytes:d.bytes,...d.controller.state()}]))};},dispose(){disposed=true;unsubscribe();engine.setDrivers('spi-gpio',[]);}};
}
